mapper.select:
SELECT fingerprint_enabled AS fingerprintEnabled,
       enabled_time AS enabledTime
FROM vm_fingerprint_switch_t
WHERE user_id = #{userId}
  AND device_id = #{deviceId}
  AND delete_flag = 0

mapper.update:
UPDATE vm_fingerprint_switch_t
SET enabled_time = NOW(),
    update_time = NOW()
WHERE user_id = #{userId}
  AND device_id = #{deviceId}
  AND delete_flag = 0
